swer.type === \"text\" && grading_result.displayAnswer.value) {\n            wrappedDisplayAnswer = {\"type\": \"text\", \"value\": \"\\\\mathbf{\" + grading_result.displayAnswer.value + \"}\"};\n        }\n\n        if (!grading_result.feedback || grading_result.feedback.type !== \"text\" || grading_result.feedback.value === null) {\n            return { ...grading_result, displayAnswer: wrappedDisplayAnswer };\n        } else if (grading_result.isCorrect) {\n            return { isCorrect: grading_result.isCorrect, feedback: {\"type\": \"text\", \"value\": \"\\\\text{\" + grading_result.feedback.value + \"}\"} , displayAnswer: wrappedDisplayAnswer };\n        } else {\n            let incorrect_string = grading_result.feedback.value;\n            let incorrect_string_split_index = incorrect_string.indexOf(\":\");\n            if (incorrect_string_split_index === -1) {\n                return { isCorrect: grading_result.isCorrect, feedback: {\"type\": \"text\", \"value\": \"\\\\text{\" + grading_result.feedback.value + \"}\"} , displayAnswer: wrappedDisplayAnswer };\n            }\n            return { isCorrect: grading_result.isCorrect, feedback: {\"type\": \"text\", \"value\": \"\\\\text{\" + incorrect_string.substring(0, incorrect_string_split_index) + \": }\" + incorrect_string.substring(incorrect_string_split_index + 1)} , displayAnswer: wrappedDisplayAnswer };\n        }\n    }",
